files.content:
.wrapper {
  border-radius: 1rem;
  overflow: visible;
}

.animated {
  --_margin-gap: 1.5rem;
  --ease: linear(
    0 0%,
    0.2688 9.91%,
    0.3859 15%,
    0.4917 20.19%,
    0.5865 25.5%,
    0.6705 30.93%,
    0.7441 36.51%,
    0.8075 42.26%,
    0.8593 47.98%,
    0.9022 53.93%,
    0.9366 60.13%,
    0.963 66.67%,
    0.9812 73.4%,
    0.9929 80.76%,
    0.9986 88.89%,
    1 100%
  );
  --bounce-duration: calc((1 / var(--speed, 1)) * 1s);
  --duration: calc((0.36 / var(--speed, 1)) * 1s);

  outline: 1px solid;

  transition-property: transform, border-radius;
  transition-duration: var(--duration);
  transition-timing-function: var(--ease);
  transform-style: preserve-3d;
  perspective: 120px;
}

.animated:has(~ .animated[data-active="true"]) {
  transform: translate3d(0, calc(var(--_margin-gap) * -1), 0);
}

.animated[data-active="true"] ~ .animated {
  transform: translate3d(0, calc(var(--_margin-gap) * 1), 0);
}

.animated:is(:first-child) {
  border-top-left-radius: 1rem;
  border-top-right-radius: 1rem;
}

.animated:is(:last-child) {
  border-bottom-left-radius: 1rem;
  border-bottom-right-radius: 1rem;
}

.animated[data-active="true"] {
  border-radius: 1rem;
}

.animated[data-active="true"] + .animated {
  border-top-left-radius: 1rem;
  border-top-right-radius: 1rem;
}

.animated:has(+ .animated[data-active="true"]) {
  border-bottom-left-radius: 1rem !important;
  border-bottom-right-radius: 1rem !important;
}

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import { motion, useReducedMotion } from "motion/react";
import {
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  ViewTransition,
} from "react";
import { cn } from "@/lib/utils";
import AnimatedPlusMinusButton from "./animated-plus-minus-button";
import styles from "./styles.module.css";

// Types
type AccordionVariant = "default" | "outlined" | "splitted" | "animated";

interface AccordionProps {
  /** The content to be displayed inside the accordion. */
  children: ReactNode;
  /**
   * Allows multiple accordion items to be open at the same time.
   * @default false
   */
  allowMultiple?: boolean;
  /** Additional CSS classes for the accordion container. */
  className?: string;
  /**
   * The visual style of the accordion.
   * @default default
   */
  variant?: AccordionVariant;
}

const accordionWrapperVariants = cva(
  "flex flex-col overflow-clip rounded-2xl",
  {
    variants: {
      variant: {
        default: "overflow-clip rounded-2xl",
        outlined: "overflow-clip rounded-2xl",
        splitted: "overflow-clip rounded-2xl",
        animated: styles.wrapper,
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

const accordionItemVariants = cva(
  "relative overflow-hidden bg-background text-foreground transition-all duration-300",
  {
    variants: {
      variant: {
        default: "border-b border-border",
        outlined:
          "border-foreground border-t border-x last:border-b first:rounded-t-2xl last:rounded-b-2xl",
        splitted: "rounded-2xl ",
        animated: styles.animated,
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

interface AccordionItemProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof accordionItemVariants> {
  children: ReactNode;
  className?: string;
  style?: React.CSSProperties;
  value?: string;
}

interface AccordionItemHeaderProps {
  value: string;
  children: ReactNode;
}
interface AccordionItemTriggerProps {
  value: string;
  children: ReactNode;
}

interface AccordionItemContentProps {
  children: ReactNode;
  value: string;
}

const AccordionContext = createContext<{
  openItems: Set<string>;
  toggleItem: (value: string) => void;
  variant: AccordionVariant;
  /** Prefix used to pair each trigger with its content for aria wiring. */
  idPrefix: string;
} | null>(null);

const AccordionRoot = ({
  children,
  allowMultiple = false,
  className,
  variant = "default",
}: AccordionProps) => {
  const [openItems, setOpenItems] = useState<Set<string>>(new Set());
  const idPrefix = useId();
  const toggleItem = (v: string) => {
    setOpenItems((prev) => {
      const newOpenItems = new Set(prev);
      if (newOpenItems.has(v)) {
        newOpenItems.delete(v);
      } else {
        if (!allowMultiple) newOpenItems.clear();
        newOpenItems.add(v);
      }
      return newOpenItems;
    });
  };

  return (
    <AccordionContext.Provider
      value={{ openItems, toggleItem, variant, idPrefix }}
    >
      <ViewTransition>
        <div
          role="presentation"
          className={cn(
            accordionWrapperVariants({ variant }),
            variant === "splitted" && "gap-y-2",
            className,
          )}
        >
          {children}
        </div>
      </ViewTransition>
    </AccordionContext.Provider>
  );
};

const AccordionItem = ({
  children,
  className,
  style,
  value,
  ...props
}: AccordionItemProps) => {
  const context = useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionItem must be used within AccordionRoot");
  const { variant, openItems } = context;
  return (
    <div
      role="presentation"
      className={cn(accordionItemVariants({ variant }), className)}
      style={style}
      data-active={value !== undefined && openItems.has(value)}
      {...props}
    >
      <div className="relative">{children}</div>
    </div>
  );
};

const AccordionItemHeader = ({ value, children }: AccordionItemHeaderProps) => {
  const context = useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionItemHeader must be used within AccordionRoot");
  const { openItems } = context;

  const isOpen = openItems.has(value);

  return (
    <div className="flex items-center justify-between py-4 px-8 font-medium text-balance rounded-xl">
      <div className="">{children}</div>
      <AnimatedPlusMinusButton isOpen={isOpen} />
    </div>
  );
};

const AccordionItemTrigger = ({
  value,
  children,
}: AccordionItemTriggerProps) => {
  const context = useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionItemTrigger must be used within AccordionRoot");

  const { openItems, toggleItem, idPrefix } = context;
  const isOpen = openItems.has(value);

  return (
    <button
      type="button"
      id={`${idPrefix}-${value}-trigger`}
      aria-expanded={isOpen}
      aria-controls={`${idPrefix}-${value}-content`}
      onClick={() => toggleItem(value)}
      className="block w-full cursor-pointer text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
    >
      {children}
    </button>
  );
};

const AccordionItemContent = ({
  children,
  value,
}: AccordionItemContentProps) => {
  const context = useContext(AccordionContext);
  if (!context)
    throw new Error("AccordionItemContent must be used within AccordionRoot");

  const { openItems, idPrefix } = context;
  const isOpen = openItems.has(value);
  const shouldReduceMotion = useReducedMotion();

  const ref = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState(0);

  // Keep the measured height in sync with content reflow (resize, wrapping).
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const measure = () => setHeight(el.offsetHeight);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const motionVariants = {
    open: { opacity: [0, 1], y: [10, 0] },
    exit: { opacity: [1, 0.1, 0], y: [0, 10] },
  };

  return (
    <motion.div
      role="region"
      id={`${idPrefix}-${value}-content`}
      aria-labelledby={`${idPrefix}-${value}-trigger`}
      aria-hidden={!isOpen}
      inert={!isOpen}
      className="overflow-hidden text-sm"
      initial={false}
      animate={{ height: isOpen ? height : 0 }}
      transition={
        shouldReduceMotion
          ? { duration: 0 }
          : { duration: 0.26, ease: [0.23, 1, 0.32, 1] }
      }
    >
      <motion.div
        initial={false}
        animate={isOpen ? "open" : "exit"}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : {
                duration: 0.3,
                ease: "easeOut",
                delay: isOpen ? 0.1 : 0,
                type: "tween",
              }
        }
        variants={motionVariants}
        ref={ref}
        className="px-8 pb-2"
      >
        {children}
      </motion.div>
    </motion.div>
  );
};

export {
  AccordionContext,
  AccordionItem,
  AccordionItemContent,
  AccordionItemHeader,
  AccordionItemTrigger,
  AccordionRoot,
};

"use client";
import { motion } from "motion/react";

interface AnimatedPlusMinusButtonProps {
  size?: number;
  isOpen?: boolean;
}
const AnimatedPlusMinusButton = ({
  size = 24,
  isOpen = false,
}: AnimatedPlusMinusButtonProps) => {
  return (
    <span aria-hidden="true" className="flex items-center justify-center">
      <motion.svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        initial="closed"
        animate={isOpen ? "open" : "closed"}
      >
        {/* Horizontal line */}
        <motion.line
          x1="1"
          y1="12"
          x2="23"
          y2="12"
          stroke="currentColor"
          strokeWidth="1"
          variants={{
            closed: { opacity: 1 },
            open: { opacity: 0 },
          }}
          transition={{ duration: 0.3 }}
        />

        {/* Vertical line */}
        <motion.line
          x1="12"
          y1="1"
          x2="12"
          y2="23"
          stroke="currentColor"
          strokeWidth="1"
          variants={{
            closed: { rotate: 0, opacity: 1 },
            open: { rotate: 90, opacity: 1 },
          }}
          transition={{ duration: 0.3 }}
        />
      </motion.svg>
    </span>
  );
};

export default AnimatedPlusMinusButton;
